using System;using System.Collections.Generic;using System.IO;using System.Text;using System.Globalization;using Nini.Config;using OpenMetaverse;
interface IGroupsModule{}interface IUserManagement{}interface IProfileModule{}
class GridInfo{public string Name;public GridInfo(string n){Name=n;}}
class Groups:IGroupsModule{public string Name;public Groups(string n){Name=n;}}
class Users:IUserManagement{public string Name;public Users(string n){Name=n;}}
class IClientAPI{}
class OSHTTPURI{public bool IsResolvedHost,IsValidHost;public string URI;public OSHTTPURI(string s,bool resolve){F.Trace+="uri:"+F.T(s)+";";F.Fail(4,"uri");if((F.Flags&8388608)!=0){var real=new Real.OSHTTPURI(s,true);IsValidHost=real.IsValidHost;IsResolvedHost=real.IsResolvedHost;URI=real.URI;return;}IsValidHost=(F.Flags&2)==0;IsResolvedHost=(F.Flags&3)==0;URI="normalized/"+s;}}
class Log{public void Debug(string s){F.Trace+="D:"+s+";";F.Fail(8,"debug");}public void Error(string s){F.Trace+="E:"+s+";";F.Fail(16,"error");}public void ErrorFormat(string s,params object[] a)=>Error(string.Format(CultureInfo.InvariantCulture,s,a));}
class Commands{public List<Action<string,string[]>> Handlers=new();public void AddCommand(string module,bool shared,string cmd,string help,string desc,Action<string,string[]> handler){F.Trace+="cmd:"+module+":"+(shared?1:0)+":"+cmd+":"+help+":"+desc+";";F.Fail(32,"command");Handlers.Add(handler);}}
class MainConsole{public static MainConsole Instance=new();public Commands Commands=new();public void Output(string s){F.Trace+="out:"+s+";";F.Fail(1048576,"output");}}
class Cache{public string Name;public int Count;public int Fault;public void Clear(){F.Trace+="clear:"+Name+";";F.Fail(Fault,Name);Count=0;}}
class StackCount{int n,flag;public StackCount(int n,int f){this.n=n;flag=f;}public int Count{get{F.Trace+=(n==2?"local;":"hg;");F.Fail(flag,n==2?"local":"hg");return n;}}}
class Events{public string Name;public Action<IClientAPI> New;public Action<UUID,Scene> Closed;public event Action<IClientAPI> OnNewClient{add{F.Trace+="new-sub:"+Name+";";F.Fail(8192,"new-sub");New+=value;}remove{New-=value;}}public event Action<UUID,Scene> OnClientClosed{add{F.Trace+="closed-sub:"+Name+";";F.Fail(16384,"closed-sub");Closed+=value;}remove{Closed-=value;}}}
class Scene{public string Id;public Events EventManager;GridInfo grid;Groups groups;Users users;public Scene(string n){Id=n;EventManager=new Events{Name=n};grid=new(n);groups=new(n);users=new(n);}public string Name{get{F.Trace+="name:"+Id+";";F.Fail(524288,"name");return (F.Flags&262144)!=0?null:Id;}}public GridInfo SceneGridInfo{get{F.Trace+="grid:"+Id+";";F.Fail(128,"grid");return (F.Flags&64)!=0?null:grid;}}public void RegisterModuleInterface<T>(T p){F.Trace+="register:"+Id+";";F.Fail(256,"register");}public T RequestModuleInterface<T>()where T:class{if(typeof(T)==typeof(IGroupsModule)){F.Trace+="groups:"+Id+";";F.Fail(1024,"groups");return (F.Flags&512)!=0?null:groups as T;}F.Trace+="users:"+Id+";";F.Fail(4096,"users");return (F.Flags&2048)!=0?null:users as T;}}
partial class Original: IProfileModule{
 static Log m_log=new();bool m_allowUserProfileWebURLs=true;GridInfo m_thisGridInfo;IGroupsModule m_groupsModule;IUserManagement m_userManagementModule;
 Cache m_profilesCache=new(){Name="profiles",Count=7,Fault=32768},m_classifiedCache=new(){Name="classifieds",Count=8,Fault=65536},m_classifiedInterest=new(){Name="interest",Count=9,Fault=131072};
 StackCount m_asyncLocalRequests=new(2,2097152),m_asyncHGRequests=new(3,4194304);
 void OnNewClient(IClientAPI client){F.Trace+="new:"+(client==null?0:1)+";";}void OnClientClosed(UUID id,Scene scene){F.Trace+="closed:"+(scene==null?"N":scene.Id)+";";}
 public void Status()=>HandleShowStatus("",null);
 public string State()=> (Enabled?1:0)+":"+(m_allowUserProfileWebURLs?1:0)+":"+F.T(ProfileServerUri)+":"+(Scene?.Id??"N")+":"+(m_thisGridInfo?.Name??"N")+":"+((Groups)m_groupsModule)?.Name+":"+((Users)m_userManagementModule)?.Name+":"+(Config==null?0:1)+":"+m_profilesCache.Count+":"+m_classifiedCache.Count+":"+m_classifiedInterest.Count;
}
static class F{
 public static int Flags;public static string Trace;
 public static void Fail(int f,string msg){if((Flags&f)!=0)throw new Exception(msg);}
 public static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();public static string T(string s){if(s==null)return "-";var b=new byte[s.Length*2];for(int i=0;i<s.Length;i++){b[i*2]=(byte)s[i];b[i*2+1]=(byte)(s[i]>>8);}return Convert.ToHexString(b).ToLowerInvariant();}
 static string Decode(string s)=>s=="."?"":Encoding.UTF8.GetString(Convert.FromHexString(s));
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var parts=line.Split(' ');Flags=int.Parse(parts[0]);Trace="";MainConsole.Instance=new();var module=new Original();var a=new Scene("A");var b=new Scene("B");var output=new List<string>();foreach(var token in parts[1..]){string result="OK";try{if(token[0]=='I')module.Initialise(token[1..]=="-"?null:new IniConfigSource(new StringReader(Decode(token[1..]))));else switch(token){case "W":module.Config=null;break;case "U":module.ProfileServerUri="manual";break;case "A":module.AddRegion(a);break;case "B":module.AddRegion(b);break;case "N":module.AddRegion(null);break;case "L":module.RegionLoaded(b);break;case "Z":module.RegionLoaded(null);break;case "R":module.RemoveRegion(null);break;case "C":module.Close();break;case "S":module.Status();break;case "X":foreach(var fn in MainConsole.Instance.Commands.Handlers.ToArray())fn("",null);break;case "E":a.EventManager.New?.Invoke(null);break;case "F":b.EventManager.New?.Invoke(new IClientAPI());break;case "D":a.EventManager.Closed?.Invoke(UUID.Zero,b);break;case "T":b.EventManager.Closed?.Invoke(UUID.Zero,null);break;}}catch(Exception e){result="EX:"+H(e.Message);}output.Add(result+":"+module.State());}Console.WriteLine(string.Join('/',output)+"|"+H(Trace));}}
}
